const lista = Array.from({ length: 2000 }, (_, i) => ({ id: i, libro: 'Juan', cap: 3, ver: (i % 36) + 1, texto: 'Porque de tal manera amó Dios al mundo, que ha dado a su Hijo unigénito' }));
const mediana = (f, n = 15) => { f(); const a = []; for (let i = 0; i < n; i++) { const t = performance.now(); f(); a.push(performance.now() - t); } a.sort((x, y) => x - y); return a[n >> 1]; };
const texto = JSON.stringify(lista);
console.log('Lista de 2000 objetos como texto JSON:', texto.length, 'caracteres');
console.log('Escribir y volver a leer (mediana):', mediana(() => JSON.parse(JSON.stringify(lista))).toFixed(2), 'ms');
console.log('Pasarla por referencia (mediana):', mediana(() => { const ref = lista; return ref.length; }).toFixed(4), 'ms');

